SELECT COUNT(*) FROM AI_DETECTION_EVENT
 WHERE PARKING_SPACE_ID = #{parkingSpaceId}
   AND DBMS_LOB.INSTR(RAW_PAYLOAD, #{needle}) > 0

SELECT MAX(DETECTED_AT) FROM AI_DETECTION_EVENT
 WHERE PARKING_SPACE_ID = #{parkingSpaceId}
   AND DBMS_LOB.INSTR(RAW_PAYLOAD, '"event_type":"PARKING_OCCUPANCY"') > 0

mapper.update:
UPDATE PARKING_SPACE
   SET SPACE_STATUS_CODE = #{status}, UPDATED_AT = SYSDATE
 WHERE PARKING_SPACE_ID = #{parkingSpaceId}
